{
  "avaliacoes": [
    {
      "id": "E154caa7b6599c343",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A escolha do tipo e da geometria da ancoragem em unidade flutuante é apresentada como dependente principalmente do tipo de embarcação, da operação, da quantidade de risers, do custo e da profundidade do mar.",
          "trechos": [
            "E154caa7b6599c343:0:690"
          ],
          "condicoes": [
            "o trecho trata de seleção de configuração de linhas de ancoragem para estruturas offshore",
            "a classificação citada inclui catenária convencional, raio curto taut leg e ancoragens verticais com tendões"
          ],
          "limites": [
            "não fornece método de dimensionamento nem pesos relativos entre os critérios",
            "não explicita critérios numéricos de aceitação para offset, excursão ou tensão"
          ]
        },
        {
          "proposicao": "Na ancoragem em catenária livre, o trecho associa a configuração a maiores deslocamentos da plataforma e afirma que o atrito do trecho de linha apoiado no leito marinho absorve parte das solicitações, reduzindo esforços na âncora.",
          "trechos": [
            "E154caa7b6599c343:690:1388"
          ],
          "condicoes": [
            "linhas com forma de catenária sob ação do próprio peso",
            "existência de grande trecho apoiado no leito marinho"
          ],
          "limites": [
            "o mecanismo é descrito qualitativamente",
            "não quantifica a parcela de solicitação absorvida nem a redução de carga na fundação"
          ]
        },
        {
          "proposicao": "A configuração taut leg é descrita como usando linhas inclinadas e tracionadas, com menor comprimento de linha, maior rigidez do sistema e limitação do passeio da embarcação, exigindo âncoras com alta resistência a carga axial de arrancamento.",
          "trechos": [
            "E154caa7b6599c343:1388:2088",
            "E154caa7b6599c343:2088:2259"
          ],
          "condicoes": [
            "comparação com configuração em catenária",
            "linhas sem geometria típica de grande trecho apoiado no leito"
          ],
          "limites": [
            "o ângulo de topo está apagado",
            "não informa faixas de profundidade, critérios de pré-tensionamento ou limites de carga vertical"
          ]
        }
      ]
    },
    {
      "id": "E95d1bc1e823bd681",
      "pertinente": true,
      "tipo": "opiniao",
      "achados": [
        {
          "proposicao": "O trecho apresenta como parâmetros de seleção do sistema de ancoragem o arranjo dos poços, o número de poços e a unidade estacionária de produção.",
          "trechos": [
            "E95d1bc1e823bd681:0:693"
          ],
          "condicoes": [
            "o texto está inserido em um trabalho que considera sistemas convencionais, turret, pernas atirantadas e cabo-guia",
            "a seleção é tratada no contexto de pré-seleção de UEP"
          ],
          "limites": [
            "é uma formulação do autor para o estudo, não uma norma",
            "não inclui resposta acoplada casco-risers-ancoragem nem critérios quantitativos de excursão"
          ]
        },
        {
          "proposicao": "No contexto do trabalho, é afirmado que, para FPSO com número alto de poços e arranjo satélite, o sistema convencional seria mais adequado do que turret em razão de limitação de número de poços atribuída ao turret.",
          "trechos": [
            "E95d1bc1e823bd681:693:1393"
          ],
          "condicoes": [
            "aplicado a FPSO",
            "número de poços alto",
            "arranjo dos poços do tipo satélite"
          ],
          "limites": [
            "trata-se de juízo do trabalho, sem base quantitativa apresentada no trecho",
            "não explicita qual limitação de número de poços ocorre nem sua faixa de validade"
          ]
        },
        {
          "proposicao": "O texto afirma que unidades com posicionamento dinâmico mantêm posição por propulsores dentro de um raio permitido para operação e menciona que, à época do trecho, seu uso em produção permanente ainda não havia sido empregado, embora houvesse estudos para águas ultra-profundas onde ancoragens se tornariam inviáveis.",
          "trechos": [
            "E95d1bc1e823bd681:1393:2091"
          ],
          "condicoes": [
            "referido a navio com DPS",
            "contexto temporal do documento"
          ],
          "limites": [
            "não define o raio permitido",
            "a menção a não utilização permanente é contextual ao documento e pode não valer fora desse recorte temporal"
          ]
        }
      ]
    },
    {
      "id": "E41098907196f127c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O trecho sustenta que, em alguns problemas de projeto offshore, as condições de projeto dependem simultaneamente do estado do mar e da resposta estrutural, de modo que considerar apenas uma elevação ou um mar centenário pode ser insuficiente sem incorporar a resposta da estrutura.",
          "trechos": [
            "E41098907196f127c:0:700"
          ],
          "condicoes": [
            "exemplos citados incluem air-gap de plataforma e embarque d'água no convés de navio ancorado",
            "aplicado a projeto baseado em resposta"
          ],
          "limites": [
            "o trecho não fornece procedimento analítico completo",
            "não explicita critérios probabilísticos ou de combinação de ações"
          ]
        },
        {
          "proposicao": "Para FPSOs com turret na proa, o projeto é descrito como altamente influenciado pelos movimentos estáticos e dinâmicos do navio, e a sensibilidade dos coeficientes hidrodinâmicos ao período da onda incidente torna importante a acurácia desse período na análise.",
          "trechos": [
            "E41098907196f127c:700:1388"
          ],
          "condicoes": [
            "FPSOs utilizando navios tipo VLCC com turret na proa",
            "mares severos",
            "dimensões do casco da ordem do comprimento de onda"
          ],
          "limites": [
            "não apresenta valores de sensibilidade nem critérios de erro aceitável",
            "o recorte é específico para essa classe de embarcação e condição de mar"
          ]
        },
        {
          "proposicao": "Em análises usuais citadas no trecho, o yaw é frequentemente tratado de forma quase-estática; em navios com turret, a rotação livre permite aproamento mais favorável e reduz carregamento estático transferido à ancoragem e aos risers, mas torna o sistema sensível à direcionalidade relativa de vento, onda e correnteza.",
          "trechos": [
            "E41098907196f127c:1388:2085",
            "E41098907196f127c:2085:2240"
          ],
          "condicoes": [
            "navio pode girar livremente por causa da ancoragem com turret",
            "a orientação e o offset estático são determinados pelas componentes constantes das forças ambientais"
          ],
          "limites": [
            "a descrição sobre análises comerciais é geral e não esgota métodos disponíveis",
            "não quantifica a redução de carregamento nem o grau de sensibilidade direcional"
          ]
        }
      ]
    },
    {
      "id": "E660c5a902b7067d5",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na ancoragem em ponto único por turret, as linhas convergem para um mesmo ponto e a estrutura com rolamentos, geralmente na proa, permite o giro do navio em torno do sistema de ancoragem e dos risers, enquanto swiveis fazem a transferência de fluidos entre partes estacionária e móvel.",
          "trechos": [
            "E660c5a902b7067d5:0:700"
          ],
          "condicoes": [
            "aplicado a FPSOs",
            "riser e sistema de ancoragem estacionários em relação ao fundo"
          ],
          "limites": [
            "o trecho descreve arquitetura e função, sem critérios de seleção ou dimensionamento",
            "não trata de limites operacionais de rotação, fadiga ou falha"
          ]
        },
        {
          "proposicao": "Na ancoragem distribuída, o trecho informa que os risers são geralmente conectados a um dos bordos, deixando o outro livre para operações de transferência de cargas.",
          "trechos": [
            "E660c5a902b7067d5:700:1399"
          ],
          "condicoes": [
            "aplicado ao arranjo de FPSO com spread mooring"
          ],
          "limites": [
            "o uso de 'geralmente' indica caráter descritivo, não universal",
            "não apresenta implicações quantitativas para offset, heading ou operações simultâneas"
          ]
        },
        {
          "proposicao": "O DICAS é apresentado como caso particular de ancoragem distribuída em que as linhas de popa são menos tensionadas que as de proa, permitindo alguma liberdade de alinhamento com as condições ambientais.",
          "trechos": [
            "E660c5a902b7067d5:700:1399"
          ],
          "condicoes": [
            "diferença de tensionamento entre linhas de proa e popa"
          ],
          "limites": [
            "o valor angular está apagado",
            "não informa critérios para definir o tensionamento diferencial nem o envelope operacional correspondente"
          ]
        }
      ]
    },
    {
      "id": "Ed0bbb7c242285b2e",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "E7939c73ca7bdc7c1",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O trecho descreve FPSOs como unidades flutuantes estacionárias de produção, armazenamento e escoamento, com grande área de convés e limitações em condições ambientais severas devido a movimentos significativos de roll, pitch e heave.",
          "trechos": [
            "E7939c73ca7bdc7c1:0:695",
            "E7939c73ca7bdc7c1:695:1385"
          ],
          "condicoes": [
            "aplicado a FPSOs como classe de unidade flutuante"
          ],
          "limites": [
            "não compara quantitativamente com outras UEPs",
            "não traduz esses movimentos em critérios de excursão, fadiga ou integridade de risers"
          ]
        },
        {
          "proposicao": "O texto informa que o sistema de ancoragem do FPSO pode ser convencional ou turret, e descreve o sistema convencional no trecho como SPM, incluindo as subdivisões CALM e SALM.",
          "trechos": [
            "E7939c73ca7bdc7c1:695:1385"
          ],
          "condicoes": [
            "classificação apresentada no documento"
          ],
          "limites": [
            "a terminologia do trecho pode divergir de outras classificações técnicas usuais",
            "não estabelece critérios para escolher entre essas alternativas"
          ]
        },
        {
          "proposicao": "No sistema turret, o trecho afirma que a ancoragem em um ponto localizado na proa concentra linhas de ancoragem e risers no mesmo local, possibilitando rotação completa do FPSO.",
          "trechos": [
            "E7939c73ca7bdc7c1:1385:2081"
          ],
          "condicoes": [
            "turret localizado na proa do navio"
          ],
          "limites": [
            "descreve capacidade funcional geral, sem discutir restrições por arranjo de risers, operação ou cargas ambientais",
            "não aborda resposta acoplada nem limites de heading"
          ]
        }
      ]
    }
